design.css:
/* Blossom — the Dantotsu look (docs/theme-references/dantotsu.md): pure black, one pink seed, Poppins, 16 px corners. */

/* Home opens on the profile: no app bar; its search and settings float over the banner as round buttons. */
@media (max-width: 640px) {
  [data-slot="home.header"] { position: absolute; inset: 0 0 auto; z-index: 5; padding: 12px 16px; pointer-events: none; }
  [data-slot="home.header"] [data-slot="brand"],
  [data-slot="home.header"] [data-part="brand.mark"] { visibility: hidden; }
  [data-slot="home.header"] a { pointer-events: auto; width: 52px; height: 52px; margin-left: 8px; border-radius: 999px; background: rgba(28, 28, 28, 0.9); }
}

/* The profile banner: full width, square, a slow Ken Burns drift, faded into the page. */
@keyframes blossom-ken-burns { from { transform: scale(1) translate(0, 0); } to { transform: scale(1.18) translate(-3%, -2%); } }
[data-slot="block.profile-header"] { padding: 0; }
[data-slot="block.profile-header"] > div { border-radius: 0; background: #000; overflow: hidden; }
[data-slot="block.profile-header"] [data-part="block.banner"] { animation: blossom-ken-burns 20s ease-in-out infinite alternate; }
[data-slot="block.profile-header"] > div > div:has(+ div) { background: linear-gradient(to top, #000 0%, rgba(0, 0, 0, 0.6) 45%, rgba(0, 0, 0, 0.1) 100%); }
[data-slot="block.profile-header"] [data-part="block.avatar"] { width: 52px; height: 52px; border: 0; }
[data-slot="block.profile-header"] [data-part="block.name"] { font-size: 18px; font-weight: 700; }
[data-slot="block.profile-header"] [data-part="block.stat"] { font-size: 12px; color: rgba(255, 255, 255, 0.58); }

/* Hub cards: two 72 px tiles, a centred uppercase label over a short pink underline. */
[data-slot="block.profile-header"] [data-nav-row] { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 16px; background: #000; }
[data-slot="block.profile-header"] [data-part="button"] {
  position: relative;
  display: grid;
  place-items: center;
  height: 72px;
  padding: 0 8px 6px;
  border-radius: 16px;
  background: linear-gradient(135deg, #2a1f27, #141014);
  backdrop-filter: none;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.4px;
  text-align: center;
  text-transform: uppercase;
  color: #fff;
}
[data-slot="block.profile-header"] [data-part="button"]::after {
  content: "";
  position: absolute;
  bottom: 18px;
  left: calc(50% - 32px);
  width: 64px;
  height: 2px;
  border-radius: 2px;
  background: #ff92e2;
}

/* Rows: 16 px bold titles; covers float on a soft shadow; a pink score pill and an ongoing dot. */
[data-part="row.title"], [data-part="block.title"] { font-size: 16px; font-weight: 700; }
[data-part="blossom.cover"] > .theme-artwork { box-shadow: 0 8px 14px rgba(0, 0, 0, 0.55); }
[data-part="blossom.score"] { margin: 6px; background: #ff92e2; }
[data-part="blossom.ongoing"] { width: 16px; height: 16px; margin: 8px; border-radius: 999px; background: #7ee07e; border: 2px solid #000; }
[data-part="blossom.title"] { line-height: 1.25; min-height: 2.5em; }

/* Series page: the floating 16 px cover, a four-line title, the outlined full-width list button. */
[data-slot="detail"] [data-part="detail.poster"] { border-radius: 16px; box-shadow: 0 16px 30px rgba(0, 0, 0, 0.6); }
[data-slot="detail"][data-variant="phone"] [data-part="detail.title"] { font-size: 18px; font-weight: 700; -webkit-line-clamp: 4; }
[data-slot="detail"] [data-part="detail.alt-title"] { display: none; }
[data-part="detail.list-button"][data-variant="full"] { height: 48px; border: 1.5px solid #fff; border-radius: 16px; color: #ff92e2; font-size: 14px; font-weight: 700; letter-spacing: 0.6px; }

/* Facts as a table: a dim bold label, a bright bold value at the end. */
[data-part="detail.facts"][data-variant="table"] [data-part="fact.label"] { font-weight: 700; color: rgba(237, 224, 230, 0.58); }
[data-part="detail.facts"][data-variant="table"] [data-part="fact.value"] { font-weight: 700; text-align: end; }

/* The pill nav: only the active tab shows its label, uppercase and bold, with the line at the bottom edge. */
[data-slot="nav.bottom"] [data-part="nav.item.label"] { text-transform: uppercase; font-weight: 700; }
[data-slot="nav.bottom"] [data-part="nav.item"][data-active] > span:first-child:not([data-part]) { top: auto; bottom: 4px; left: 22px; right: 22px; height: 3px; }

/* Series tabs: the page's own bottom bar, 64 px, a rounded pink indicator on top of the active tab. */
[data-part="tabs"][data-variant="bottom"] [data-part="tab"] { position: relative; padding: 22px 0 20px; font-size: 11px; letter-spacing: 0.2px; }
[data-part="tabs"][data-variant="bottom"] [data-part="tab"][data-active]::before {
  content: "";
  position: absolute;
  top: 0;
  left: 26%;
  right: 26%;
  height: 3px;
  border-radius: 0 0 3px 3px;
  background: #ff92e2;
}
[data-part="detail.facts"][data-variant="table"] { max-width: 560px; }
